custom_css:
/* 暖木狐狸小酒馆。适用于酒馆默认聊天布局。 */
@import url("https://cdn.jsdelivr.net/npm/lxgw-wenkai-screen-webfont/style.css");

:root {
    --fox-ink: #492b20;
    --fox-gold: #a96324;
    --fox-cream: #fff2d8;
    --fox-wood: #4d2b18;
    --fox-green: #526144;
    --fox-gap: 8px;
    --fox-rail: clamp(42px, 8vw, 58px);
    --fox-rail-top: 55px;
    --fox-rail-bottom: 52px;
    --fox-rail-inset: max(4px, env(safe-area-inset-left, 0px));
    --fox-main-start: calc(var(--fox-rail-inset) + var(--fox-rail) + var(--fox-gap));
    --fox-top: max(6px, env(safe-area-inset-top, 0px));
    --fox-bottom: max(6px, env(safe-area-inset-bottom, 0px));
    --fox-touch-size: clamp(40px, 11vw, 44px);
    --fox-font: "LXGW WenKai Screen", "PingFang SC", "Microsoft YaHei", sans-serif;
    --topBarBlockSize: 0px;
}

body { font-family: var(--fox-font); }

/* The theme supplies a page backdrop, including over chat-specific backgrounds. */
body #bg1,
body #bg_custom {
    background-color: #f1e4df !important;
    background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@de8303320e700b97f56acc66d341a5b834c8652b/fox-tavern/page-background.jpg") !important;
    background-position: center center !important;
    background-repeat: no-repeat !important;
    background-size: cover !important;
}
@media (min-aspect-ratio: 1/1) {
    body #bg1,
    body #bg_custom {
        background-size: auto 100% !important;
    }
}


/* Give the decoration and buttons the same fixed viewport area. */
body #top-bar#top-bar#top-bar,
body #top-settings-holder#top-settings-holder#top-settings-holder {
    position: fixed !important;
    top: var(--fox-top) !important;
    right: auto !important;
    bottom: auto !important;
    left: var(--fox-rail-inset) !important;
    width: var(--fox-rail) !important;
    min-width: 0 !important;
    max-width: none !important;
    height: calc(100vh - var(--fox-top) - var(--fox-bottom)) !important;
    height: calc(100dvh - var(--fox-top) - var(--fox-bottom)) !important;
    min-height: 0 !important;
    max-height: none !important;
    margin: 0 !important;
    border: 0 !important;
    transform: none !important;
    translate: none !important;
    box-sizing: border-box !important;
}

body #top-bar#top-bar#top-bar {
    display: none !important;
}

/* Paint on the visible button holder, including on clients that hide #top-bar. */
body #top-settings-holder#top-settings-holder#top-settings-holder {
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    justify-content: flex-start !important;
    gap: 2px !important;
    padding: calc(var(--fox-rail-top) + 2px) 0 calc(var(--fox-rail-bottom) + 2px) !important;
    overflow-x: hidden !important;
    overflow-y: auto !important;
    visibility: visible !important;
    pointer-events: auto !important;
    border-radius: 12px !important;
    isolation: isolate;
    contain: none !important;
    will-change: auto !important;
    filter: none !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    background-color: var(--fox-wood) !important;
    background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@110d5dcd09a936e55275c3e7e42b92b1250f3613/fox-tavern/rail_top.png"), url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@110d5dcd09a936e55275c3e7e42b92b1250f3613/fox-tavern/rail_bot.png"), url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@110d5dcd09a936e55275c3e7e42b92b1250f3613/fox-tavern/rail_mid.png") !important;
    background-repeat: no-repeat !important;
    background-position: center top, center bottom, center var(--fox-rail-top) !important;
    background-size: 100% var(--fox-rail-top), 100% var(--fox-rail-bottom),
        100% calc(100% - var(--fox-rail-top) - var(--fox-rail-bottom) + 1px) !important;
    background-attachment: scroll !important;
    scrollbar-width: none;
    z-index: 4006 !important;
}
#top-settings-holder::-webkit-scrollbar { display: none; }

body #top-settings-holder#top-settings-holder#top-settings-holder > .drawer {
    width: 100% !important;
    height: auto !important;
    min-height: var(--fox-touch-size) !important;
    position: static !important;
    flex: 0 0 auto !important;
    overflow: visible !important;
    pointer-events: auto !important;
}
#top-settings-holder#top-settings-holder#top-settings-holder > .drawer > .drawer-toggle {
    display: flex !important;
    align-items: stretch !important;
    justify-content: center !important;
    width: 100% !important;
    min-height: var(--fox-touch-size) !important;
    pointer-events: auto !important;
}
#top-settings-holder#top-settings-holder#top-settings-holder > .drawer > .drawer-toggle > .drawer-icon {
    display: grid !important;
    place-items: center !important;
    box-sizing: border-box !important;
    width: 100% !important;
    min-height: var(--fox-touch-size) !important;
    margin: 0 !important;
    padding: 0 !important;
    opacity: 1 !important;
    color: #ffe7ad !important;
    font-size: 20px !important;
    text-shadow: 0 1px 3px #35180b;
    background: var(--fox-nav-art, none) center / 27px 27px no-repeat !important;
    border-radius: 8px;
    pointer-events: auto !important;
    touch-action: manipulation;
    cursor: pointer;
}
#top-settings-holder > :is(#advanced-formatting-button,#extensions-settings-button,#persona-management-button,#backgrounds-button,#ai-config-button,#sys-settings-button,#WI-SP-button,#user-settings-button,#rightNavHolder)
    > .drawer-toggle > .drawer-icon::before {
    visibility: hidden;
}
#top-settings-holder > #advanced-formatting-button { --fox-nav-art: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@110d5dcd09a936e55275c3e7e42b92b1250f3613/fox-tavern/ico_pencil.png"); }
#top-settings-holder > #extensions-settings-button { --fox-nav-art: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@110d5dcd09a936e55275c3e7e42b92b1250f3613/fox-tavern/ico_plus.png"); }
#top-settings-holder > #persona-management-button { --fox-nav-art: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@110d5dcd09a936e55275c3e7e42b92b1250f3613/fox-tavern/ico_fox.png"); }
#top-settings-holder > #backgrounds-button { --fox-nav-art: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@110d5dcd09a936e55275c3e7e42b92b1250f3613/fox-tavern/ico_lantern.png"); }
#top-settings-holder > #ai-config-button { --fox-nav-art: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@de8303320e700b97f56acc66d341a5b834c8652b/fox-tavern/ico_ai_config.png"); }
#top-settings-holder > #sys-settings-button { --fox-nav-art: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@de8303320e700b97f56acc66d341a5b834c8652b/fox-tavern/ico_api_connect.png"); }
#top-settings-holder > #WI-SP-button { --fox-nav-art: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@de8303320e700b97f56acc66d341a5b834c8652b/fox-tavern/ico_world_info.png"); }
#top-settings-holder > #user-settings-button { --fox-nav-art: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@de8303320e700b97f56acc66d341a5b834c8652b/fox-tavern/ico_user_settings.png"); }
#top-settings-holder > #rightNavHolder { --fox-nav-art: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@de8303320e700b97f56acc66d341a5b834c8652b/fox-tavern/ico_character_management.png"); }
#top-settings-holder#top-settings-holder#top-settings-holder > .drawer > .drawer-toggle > .drawer-icon:is(.openIcon,:focus-visible) {
    background-color: #fff0bf40 !important;
    box-shadow: inset 0 0 0 1px #f8d49099;
}

body #top-settings-holder#top-settings-holder#top-settings-holder .drawer-content.openDrawer {
    position: fixed !important;
    inset: var(--fox-top) auto auto var(--fox-main-start) !important;
    margin: 0 !important;
    width: min(760px, calc(100vw - var(--fox-main-start) - var(--fox-gap))) !important;
    max-width: calc(100vw - var(--fox-main-start) - var(--fox-gap)) !important;
    min-width: 0 !important;
    max-height: calc(100dvh - var(--fox-top) - var(--fox-bottom)) !important;
    overflow-y: auto;
    pointer-events: auto !important;
    box-sizing: border-box;
}
body #top-settings-holder#top-settings-holder#top-settings-holder .drawer-content.openDrawer:is(.fillLeft,.fillRight) {
    width: min(430px, calc(100vw - var(--fox-main-start) - var(--fox-gap))) !important;
}
body #top-settings-holder#top-settings-holder#top-settings-holder .drawer-content.openDrawer.maximized {
    width: calc(100vw - var(--fox-main-start) - var(--fox-gap)) !important;
}

body #sheld {
    inset: var(--fox-top) var(--fox-gap) var(--fox-bottom) var(--fox-main-start) !important;
    width: auto !important;
    max-width: 1100px !important;
    min-width: 0 !important;
    height: auto !important;
    max-height: none !important;
    margin: 0 auto !important;
}
body #chat {
    container-type: inline-size;
    flex: 1 1 auto !important;
    min-height: 0;
    width: 100%;
    box-sizing: border-box;
    padding-inline: 0 !important;
    background: transparent !important;
}

#chat > .mes {
    --fox-bubble: min(97cqw, 680px);
    --fox-head: calc(var(--fox-bubble) * .258333);
    --fox-foot: calc(var(--fox-bubble) * .206481);
    display: block !important;
    width: var(--fox-bubble) !important;
    max-width: 100% !important;
    flex: 0 0 auto !important;
    box-sizing: border-box;
    position: relative;
    contain: none !important;
    content-visibility: visible !important;
    contain-intrinsic-size: none !important;
    height: auto !important;
    max-height: none !important;
    overflow: visible !important;
    margin: calc(var(--fox-head) + 18px) auto var(--fox-foot) !important;
    padding: 31px 9% 12px !important;
    border: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@110d5dcd09a936e55275c3e7e42b92b1250f3613/fox-tavern/bubble_mid.png") top center / 100% auto repeat-y !important;
    color: var(--fox-ink);
}
#chat > .mes:first-of-type { margin-top: calc(var(--fox-head) + 8px) !important; }
#chat > .mes:last-of-type { margin-bottom: calc(var(--fox-foot) + 15px) !important; }

#chat > .mes::before,
#chat > .mes::after {
    content: "";
    position: absolute;
    inset-inline: 0;
    width: 100%;
    pointer-events: none;
    background-position: center;
    background-repeat: no-repeat;
    background-size: 100% 100%;
}
#chat > .mes::before {
    bottom: 100%;
    height: var(--fox-head);
    background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@110d5dcd09a936e55275c3e7e42b92b1250f3613/fox-tavern/bubble_top.png");
    z-index: 2;
}
#chat > .mes::after {
    top: calc(100% - 1px);
    height: var(--fox-foot);
    background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@110d5dcd09a936e55275c3e7e42b92b1250f3613/fox-tavern/bubble_bot.png");
}

#chat .mes .mes_block {
    position: static !important;
    width: 100% !important;
    padding: 0 !important;
    margin: 0 !important;
}
#chat .mes :is(.mes_block,.mes_text) {
    contain: none !important;
    height: auto !important;
    max-height: none !important;
}

#chat .mes :is(.mesAvatarWrapper,.ch_name) {
    position: absolute !important;
    inset: auto 0 100% !important;
    width: 100% !important;
    height: var(--fox-head) !important;
    margin: 0 !important;
    padding: 0 !important;
    pointer-events: none;
}
#chat .mes .mesAvatarWrapper .avatar {
    position: absolute !important;
    top: 20.9%;
    left: 12.15%;
    width: 15.85% !important;
    height: calc(var(--fox-bubble) * .1585) !important;
    aspect-ratio: 1;
    z-index: 1;
    margin: 0 !important;
    border-radius: 50% !important;
    box-shadow: none !important;
    overflow: hidden;
    pointer-events: auto;
}
#chat .mes .mesAvatarWrapper .avatar img {
    display: block;
    width: 100% !important;
    height: 100% !important;
    object-fit: cover;
    border: 0 !important;
    border-radius: inherit;
}
#chat .mes .mesAvatarWrapper {
    display: flex !important;
    justify-content: flex-start !important;
    align-items: flex-start !important;
    gap: 5px;
    box-sizing: border-box;
    padding: calc(var(--fox-head) * .747) 0 0 30% !important;
    z-index: auto !important;
}
#chat .mes :is(.mesIDDisplay,.mes_timer,.tokenCounterDisplay) {
    position: relative !important;
    z-index: 3;
    width: auto !important;
    margin: 0 !important;
    color: #fff1cd !important;
    font-size: clamp(8px, 2cqw, 12px) !important;
    line-height: 1.1;
    text-shadow: 0 1px 2px #24120b;
    white-space: nowrap;
}
#chat .mes .ch_name { z-index: 4; display: block !important; }
#chat .mes .name_text {
    position: absolute;
    left: 30%;
    top: 38%;
    width: 32%;
    height: 32%;
    overflow: hidden;
    display: block;
    white-space: nowrap;
    text-overflow: ellipsis;
    text-align: center;
    line-height: calc(var(--fox-head) * .32);
    font-size: clamp(12px, 3.7cqw, 23px);
    color: var(--fox-ink);
    pointer-events: auto;
}
#chat .mes .timestamp {
    position: absolute;
    top: 86%;
    left: 30%;
    font-size: clamp(8px, 2cqw, 11px);
    color: #fff1cd !important;
    text-shadow: 0 1px 3px #2b140b;
}
#chat .mes :is(.mes_buttons,.mes_edit_buttons) {
    position: absolute !important;
    top: calc(var(--fox-head) + 4px);
    right: 8%;
    margin: 0 !important;
    pointer-events: auto;
}
#chat .mes .extraMesButtons { background-color: #fff1d9; border-radius: 8px; }
#chat .mes :is(.swipe_left,.swipeRightBlock) {
    position: absolute !important;
    top: calc(100% + 3px) !important;
    bottom: auto !important;
    margin: 0 !important;
    z-index: 2;
}
#chat .mes .swipe_left { left: 8% !important; right: auto !important; }
#chat .mes .swipeRightBlock {
    right: 8% !important;
    left: auto !important;
    flex-direction: row-reverse !important;
    gap: 4px;
}
#chat .mes .swipes-counter { color: var(--fox-ink) !important; }

#chat .mes .mes_text {
    color: var(--fox-ink);
    line-height: 1.8;
    overflow-wrap: anywhere;
}
#chat .mes_text q {
    color: #85452a;
    background: linear-gradient(transparent 64%, #f0ca8060 64%);
    box-decoration-break: clone;
    -webkit-box-decoration-break: clone;
}
#chat .mes_text em { color: #755833; }
#chat .mes_text strong { color: #6c3b21; }
#chat .mes_text blockquote { border-inline-start: 3px solid #b88449; background: #fff7e58c; }
#chat .mes_text :is(pre,code) { background: #fff9eb; color: var(--fox-ink); }
#chat .mes_text hr {
    border: 0;
    height: 20px;
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@110d5dcd09a936e55275c3e7e42b92b1250f3613/fox-tavern/deco_divider.png") center / contain no-repeat;
}
#chat .mes_reasoning_header {
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@110d5dcd09a936e55275c3e7e42b92b1250f3613/fox-tavern/deco_reason.png") left center / 21px auto no-repeat;
    padding-left: 26px;
}
#chat #show_more_messages {
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@110d5dcd09a936e55275c3e7e42b92b1250f3613/fox-tavern/btn_loadmore.png") center / contain no-repeat !important;
    width: min(175px, 72%);
    min-height: 47px;
    margin: 5px auto;
    color: #fff6dc;
    text-shadow: 0 1px 3px #381b0b;
}

body :is(#form_sheld,#send_form) { background: transparent; }
body #send_form {
    padding: 5px 8px;
    background: var(--fox-cream);
    border: 2px solid #ac7640;
    border-radius: 14px;
    box-shadow: inset 0 0 0 2px #e5bd78, 0 2px 7px #421e1844;
    position: relative;
}
#send_form::before {
    content: "";
    position: absolute;
    right: 10px;
    bottom: calc(100% + 1px);
    width: 39px;
    height: 38px;
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@110d5dcd09a936e55275c3e7e42b92b1250f3613/fox-tavern/deco_tea.png") center / contain no-repeat;
    pointer-events: none;
}
#send_textarea { color: var(--fox-ink); background: transparent; }
#send_textarea::placeholder { color: #77563d; }
#nonQRFormItems { position: relative; }

#options_button { --fox-icon: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@110d5dcd09a936e55275c3e7e42b92b1250f3613/fox-tavern/ico_menu.png"); }
#extensionsMenuButton { --fox-icon: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@110d5dcd09a936e55275c3e7e42b92b1250f3613/fox-tavern/ico_plus.png"); }
#send_but { --fox-icon: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@110d5dcd09a936e55275c3e7e42b92b1250f3613/fox-tavern/ico_send.png"); }
#mes_stop .fa-circle-stop { --fox-icon: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@110d5dcd09a936e55275c3e7e42b92b1250f3613/fox-tavern/ico_stop.png"); }
.mes_button.mes_edit { --fox-icon: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@110d5dcd09a936e55275c3e7e42b92b1250f3613/fox-tavern/ico_pencil.png"); }
.mes_button.extraMesButtonsHint { --fox-icon: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@110d5dcd09a936e55275c3e7e42b92b1250f3613/fox-tavern/ico_more.png"); }
.mes_edit_done { --fox-icon: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@110d5dcd09a936e55275c3e7e42b92b1250f3613/fox-tavern/ico_check.png"); }
.mes_edit_cancel { --fox-icon: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@110d5dcd09a936e55275c3e7e42b92b1250f3613/fox-tavern/ico_close.png"); }
.swipe_left { --fox-icon: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@110d5dcd09a936e55275c3e7e42b92b1250f3613/fox-tavern/ico_left.png"); }
.swipe_right { --fox-icon: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@110d5dcd09a936e55275c3e7e42b92b1250f3613/fox-tavern/ico_right.png"); }
#favorite_button { --fox-icon: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@110d5dcd09a936e55275c3e7e42b92b1250f3613/fox-tavern/ico_star.png"); }
#favorite_button.fav_on { --fox-icon: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@110d5dcd09a936e55275c3e7e42b92b1250f3613/fox-tavern/ico_star_on.png"); }

:is(#options_button,#extensionsMenuButton,#send_but,#mes_stop .fa-circle-stop,.mes_button.mes_edit,.mes_button.extraMesButtonsHint,.mes_edit_done,.mes_edit_cancel,.swipe_left,.swipe_right,#favorite_button)::before {
    content: "" !important;
    display: inline-block;
    width: 23px;
    height: 23px;
    vertical-align: middle;
    background: var(--fox-icon) center / contain no-repeat;
}
:is(#options_button,#extensionsMenuButton,#send_but,#mes_stop .fa-circle-stop,.mes_edit_done,.mes_edit_cancel,.swipe_left,.swipe_right) { color: var(--fox-ink); }

#top-settings-holder .drawer-content,
:is(#floatingPrompt,#cfgConfig) {
    color: var(--fox-ink);
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@110d5dcd09a936e55275c3e7e42b92b1250f3613/fox-tavern/panel_bg.png") center top / 100% 100% no-repeat, var(--fox-cream) !important;
    border: 1px solid #ab7548;
    border-radius: 12px;
    padding: 16px;
    box-shadow: 0 8px 26px #2a160b55;
}
:is(.popup,.options-content,#toast-container .toast) {
    background-color: var(--fox-cream) !important;
    color: var(--fox-ink) !important;
    border-color: #b38454;
}
:is(.standoutHeader,#user-settings-block h4) {
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@110d5dcd09a936e55275c3e7e42b92b1250f3613/fox-tavern/deco_star.png") 5px center / 22px auto no-repeat, var(--fox-green);
    color: #fff5df;
    border-radius: 8px;
    padding-inline-start: 31px;
}
#top-settings-holder :is(input[type="text"],input[type="number"],textarea,select) {
    background: #fff9e8;
    color: var(--fox-ink);
}
.inline-drawer-icon.down::before {
    content: "" !important;
    display: inline-block;
    width: 17px;
    height: 17px;
