#top-settings-holder .api_loading::before {
    content: "";
    display: inline-block;
    width: 22px;
    height: 22px;
    margin-inline-end: 5px;
    vertical-align: middle;
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@110d5dcd09a936e55275c3e7e42b92b1250f3613/fox-tavern/ico_spinner.png") center / contain no-repeat;
    animation: fox-spin 2s linear infinite;
}
@keyframes fox-spin { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) {
    #top-settings-holder .api_loading::before { animation: none; }
